        // ── Reads current enabled/disabled state for each optimization ──────────
        private static bool ReadOptState(int index) => index switch
        {
            // 0 — Disable visual animations
            0 => ReadRegDWord(Microsoft.Win32.Registry.CurrentUser,
                     @"Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects",
"VisualFXSetting") == 2,
            // 1 — Disable telemetry DiagTrack
            1 => IsServiceDisabled("DiagTrack"),
            // 2 — Disable dmwappushservice
            2 => IsServiceDisabled("dmwappushservice"),
            // 3 — Disable WSearch
            3 => IsServiceDisabled("WSearch"),
            4 => IsServiceDisabled("XblAuthManager") && IsServiceDisabled("XblGameSave") && IsServiceDisabled("XboxNetApiSvc"),
            // 5 — Disable SysMain
            5 => IsServiceDisabled("SysMain"),
            // 6 — Disable tips & suggestions
            6 => ReadRegDWord(Microsoft.Win32.Registry.CurrentUser,
                     @"Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager",
"SubscribedContent-338388Enabled") == 0,
            // 7 — Disable activity history
            7 => ReadRegDWord(Microsoft.Win32.Registry.LocalMachine,
                     @"SOFTWARE\Policies\Microsoft\Windows\System",
"EnableActivityFeed") == 0,
            // 8 — Disable advertising ID
            8 => ReadRegDWord(Microsoft.Win32.Registry.CurrentUser,
                     @"Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo",
"Enabled") == 0,
            // 9 — High performance power plan
            9 => IsHighPerfPlanActive(),
            // 10 — Disable startup delay
            10 => ReadRegDWord(Microsoft.Win32.Registry.CurrentUser,
                      @"Software\Microsoft\Windows\CurrentVersion\Explorer\Serialize",
"StartupDelayInMSec") == 0,
            // 11 — Disable News & Interests
            11 => ReadRegDWord(Microsoft.Win32.Registry.LocalMachine,
                      @"SOFTWARE\Policies\Microsoft\Windows\Windows Feeds",
"EnableFeeds") == 0,
            _ => false
        };

        private static int ReadRegDWord(Microsoft.Win32.RegistryKey hive, string subKey, string name)
        {
            try
            {
                using var key = hive.OpenSubKey(subKey);
                return key?.GetValue(name) is int v ? v : -1;
            }
            catch { return -1; }
        }

        private static bool IsServiceDisabled(string serviceName)
        {
            try
            {
                using var key = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(
                    $@"SYSTEM\CurrentControlSet\Services\{serviceName}");
                if (key?.GetValue("Start") is int start)
                    return start == 4; // 4 = Disabled
                return false;
            }
            catch { return false; }
        }

        private static bool IsHighPerfPlanActive()
        {
            try
            {
                var psi = new System.Diagnostics.ProcessStartInfo("powercfg", "/getactivescheme")
                { RedirectStandardOutput = true, UseShellExecute = false, CreateNoWindow = true };
                using var p = System.Diagnostics.Process.Start(psi);
                string? output = p != null ? SMDWin.Services.ProcessRunner.ReadStdoutBounded(p, 3000) : null;
                p?.WaitForExit(2000);
                // High performance GUID: 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c
                return output?.Contains("8c5e7fda", StringComparison.OrdinalIgnoreCase) == true;
            }
            catch { return false; }
        }

        private void OptimizePerformance_Click(object sender, RoutedEventArgs e)
        {
            if (_optimizerOpen) return;
            _optimizerOpen = true;
            try { OptimizePerformance_Show(); }
            finally { _optimizerOpen = false; }
        }
        private void OptimizePerformance_Show()
        {
            string OL(string key) => SMDWin.Services.LanguageService.S("Optimize", key);
            var opts = new (string, string, string, Action, Action)[]
            {
                ("🎬", OL("OptAnimLabel"), OL("OptAnimDesc"),
                    () => { RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects", "VisualFXSetting", 2); SystemParameterSet("animation", false); },
                    () => { RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects", "VisualFXSetting", 1); SystemParameterSet("animation", true); }),
                ("📡", OL("OptDiagLabel"), OL("OptDiagDesc"),
                    () => SetServiceStartup("DiagTrack","Disabled"),
                    () => SetServiceStartup("DiagTrack","Automatic")),
                ("📲", OL("OptWapLabel"), OL("OptWapDesc"),
                    () => SetServiceStartup("dmwappushservice","Disabled"),
                    () => SetServiceStartup("dmwappushservice","Automatic")),
                ("🔍", OL("OptSearchLabel"), OL("OptSearchDesc"),
                    () => SetServiceStartup("WSearch","Disabled"),
                    () => SetServiceStartup("WSearch","Automatic")),
                ("🎮", OL("OptXboxLabel"), OL("OptXboxDesc"),
                    () => { SetServiceStartup("XblAuthManager","Disabled"); SetServiceStartup("XblGameSave","Disabled"); SetServiceStartup("XboxNetApiSvc","Disabled"); },
                    () => { SetServiceStartup("XblAuthManager","Automatic"); SetServiceStartup("XblGameSave","Automatic"); SetServiceStartup("XboxNetApiSvc","Automatic"); }),
                ("⚡", OL("OptSysMainLabel"), OL("OptSysMainDesc"),
                    () => SetServiceStartup("SysMain","Disabled"),
                    () => SetServiceStartup("SysMain","Automatic")),
                ("💡", OL("OptTipsLabel"), OL("OptTipsDesc"),
                    () => { RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager", "SubscribedContent-338388Enabled", 0); RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager", "SubscribedContent-338389Enabled", 0); RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager", "SoftLandingEnabled", 0); },
                    () => { RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager", "SubscribedContent-338388Enabled", 1); RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager", "SubscribedContent-338389Enabled", 1); RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager", "SoftLandingEnabled", 1); }),
                ("🕒", OL("OptActivityLabel"), OL("OptActivityDesc"),
                    () => RegSetDWord(@"SOFTWARE\Policies\Microsoft\Windows\System", "EnableActivityFeed", 0, Microsoft.Win32.Registry.LocalMachine),
                    () => RegSetDWord(@"SOFTWARE\Policies\Microsoft\Windows\System", "EnableActivityFeed", 1, Microsoft.Win32.Registry.LocalMachine)),
                ("🪧", OL("OptAdIdLabel"), OL("OptAdIdDesc"),
                    () => RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo", "Enabled", 0),
                    () => RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo", "Enabled", 1)),
                ("🔋", OL("OptPowerLabel"), OL("OptPowerDesc"),
                    () => { OptimizeBackup.Remember(OptimizeBackup.PowerKey, () => new OptimizeBackup.Entry { Exists = true, Text = ReadActiveSchemeGuid() });
                            RunCmd("powercfg", "/setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c"); },
                    () => { var prev = OptimizeBackup.Take(OptimizeBackup.PowerKey);   // the plan that was active before, not a fixed one
                            string guid = !string.IsNullOrWhiteSpace(prev?.Text) ? prev!.Text : "381b4222-f694-41f0-9685-ff5bb260df2e";
                            RunCmd("powercfg", "/setactive " + guid); }),
                ("🚀", OL("OptStartupLabel"), OL("OptStartupDesc"),
                    () => RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\Explorer\Serialize", "StartupDelayInMSec", 0),
                    () => RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\Explorer\Serialize", "StartupDelayInMSec", 10000)),
                ("📰", OL("OptNewsLabel"), OL("OptNewsDesc"),
                    () => RegSetDWord(@"SOFTWARE\Policies\Microsoft\Windows\Windows Feeds", "EnableFeeds", 0, Microsoft.Win32.Registry.LocalMachine),
                    () => RegSetDWord(@"SOFTWARE\Policies\Microsoft\Windows\Windows Feeds", "EnableFeeds", 1, Microsoft.Win32.Registry.LocalMachine)),
            };

            // The window is in views/OptimizeDialog.cs (DialogKit, groups, discrete states, "Admin" chip, result in the footer).
            // Only the actions + the mapping stay here.
            string[] icons  = { "Icon.Display", "Icon.Shield", "Icon.Signal", "Icon.Search", "Icon.App", "Icon.Ram",
                                "Icon.Info", "Icon.History", "Icon.Lock", "Icon.Power", "Icon.Startup", "Icon.Globe" };
            string gPerf = OL("GroupPerformance"), gPriv = OL("GroupPrivacy"), gUi = OL("GroupInterface");
            string[] groups = { gUi, gPriv, gPriv, gPerf, gPerf, gPerf, gUi, gPriv, gPriv, gPerf, gPerf, gUi };
            // services (Stop/StartupType) and HKLM keys => administrator rights
            bool[] admin   = { false, true, true, true, true, true, false, true, false, false, false, true };
            var items = new List<SMDWin.Views.OptimizeItem>();
            for (int i = 0; i < opts.Length; i++)
            {
                int idx = i;
                items.Add(new SMDWin.Views.OptimizeItem
                {
                    IconKey    = i < icons.Length ? icons[i] : "Icon.Optimize",
                    Label      = opts[i].Item2,
                    Desc       = opts[i].Item3,
                    Group      = i < groups.Length ? groups[i] : gPerf,
                    NeedsAdmin = i < admin.Length && admin[i],
                    Apply      = WrapOpt(OptimizeBackup.Mode.Apply,   opts[i].Item4),
                    Revert     = WrapOpt(OptimizeBackup.Mode.Restore, opts[i].Item5),
                    IsApplied  = () => ReadOptState(idx),
                });
            }
            // Display order: Performance, Privacy, Interface
            var ordered = items.OrderBy(it => it.Group == gPerf ? 0 : it.Group == gPriv ? 1 : 2).ToList();
            var dlg = new SMDWin.Views.OptimizeDialog(ordered) { Owner = this };
            SMDWin.Views.Net.NetWindowHelper.ShowModalWithOverlay(dlg, this);
        }


        /// <summary>Puts the action in "Apply" mode (saves the original values) or "Restore" mode (brings them back).</summary>
        private static Action WrapOpt(OptimizeBackup.Mode mode, Action a) => () =>
        {
            OptimizeBackup.Current = mode;
            try { a(); }
            finally { OptimizeBackup.Current = OptimizeBackup.Mode.None; }
        };

        private static string ReadActiveSchemeGuid()
        {
            try
            {
                var psi = new System.Diagnostics.ProcessStartInfo("powercfg", "/getactivescheme")
                { RedirectStandardOutput = true, UseShellExecute = false, CreateNoWindow = true };
                using var p = System.Diagnostics.Process.Start(psi);
                string? output = p != null ? SMDWin.Services.ProcessRunner.ReadStdoutBounded(p, 3000) : null;
                p?.WaitForExit(2000);
                var m = System.Text.RegularExpressions.Regex.Match(output ?? "", "[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}");
                return m.Success ? m.Value : "";
            }
            catch { return ""; }
        }

        private static void SetServiceStartup(string serviceName, string startType)
        {
            var mode = OptimizeBackup.Current;
            string target = startType.ToLower();
            if (mode == OptimizeBackup.Mode.Restore)
            {
                // the previous startup type is restored; the service is NOT stopped on restore
                var prev = OptimizeBackup.Take(OptimizeBackup.SvcKey(serviceName));
                if (prev is { Exists: true }) target = OptimizeBackup.ScStartType(prev);
                try { RunCmd("sc", $"config \"{serviceName}\" start= {target}"); } catch (Exception logEx) { AppLogger.Warning(logEx, "Optimize.Restore " + serviceName); }
                ToolActivityLog.Add("Optimize", $"Service {serviceName}: start type restored to {target}", "ok");
                return;
            }
            if (mode == OptimizeBackup.Mode.Apply)
                OptimizeBackup.Remember(OptimizeBackup.SvcKey(serviceName), () => OptimizeBackup.ReadService(serviceName));
            try { RunCmd("sc", $"config \"{serviceName}\" start= {target}"); } catch (Exception logEx) { AppLogger.Warning(logEx, "Optimize.Apply " + serviceName); }
            if (target == "disabled")
                try { RunCmd("sc", $"stop \"{serviceName}\""); } catch (Exception logEx) { AppLogger.Warning(logEx, "Optimize.Stop " + serviceName); }
            ToolActivityLog.Add("Optimize", $"Service {serviceName}: start type set to {target}", "ok");
        }
        private static void RunCmd(string exe, string args)
        {
            var psi = new System.Diagnostics.ProcessStartInfo(exe, args)
            {
                CreateNoWindow = true, UseShellExecute = false,
                RedirectStandardOutput = true, RedirectStandardError = true,
            };
            using var p = System.Diagnostics.Process.Start(psi);
            p?.WaitForExit(3000);
        }
        private static void RegSetDWord(string subKey, string name, int value,
            Microsoft.Win32.RegistryKey? hive = null)
        {
            hive ??= Microsoft.Win32.Registry.CurrentUser;
            string hn = hive == Microsoft.Win32.Registry.LocalMachine ? "HKLM" : "HKCU";
            string key = OptimizeBackup.RegKey(hn, subKey, name);
            var mode = OptimizeBackup.Current;
            if (mode == OptimizeBackup.Mode.Apply)
                OptimizeBackup.Remember(key, () => OptimizeBackup.ReadReg(hive, subKey, name));
            if (mode == OptimizeBackup.Mode.Restore)
            {
                var prev = OptimizeBackup.Take(key);
                if (prev is { Exists: false })
                {   // the value did not exist before: it is deleted, not set to a fixed one
                    using var k = hive.OpenSubKey(subKey, true);
                    k?.DeleteValue(name, false);
                    ToolActivityLog.Add("Optimize", $"{hn}\\{subKey}\\{name}: removed (did not exist before)", "ok");
                    return;
                }
                if (prev != null) value = prev.Value;
            }
            using var key2 = hive.CreateSubKey(subKey, true);
            key2?.SetValue(name, value, Microsoft.Win32.RegistryValueKind.DWord);
            ToolActivityLog.Add("Optimize", $"{hn}\\{subKey}\\{name} = {value}", "ok");
        }
        private static void SystemParameterSet(string param, bool value)
        {
            // Disable animation: set SystemParameters via registry
            if (param == "animation")
            {
                RegSetDWord(@"Control Panel\Desktop\WindowMetrics", "MinAnimate", value ? 1 : 0);
                RegSetDWord(@"Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced", "TaskbarAnimations", value ? 1 : 0);
            }
        }
